    Type parameterType = ReflectJvmMapping.getJavaType(source);
    ResolvableType sourceResolvableType = ResolvableType.forType(parameterType);

    // Ensure handling of Kotlin-specific types or parameterization
    if (parameterType instanceof ParameterizedType) {
        ResolvableType targetResolvableType = ResolvableType.forClassWithGenerics(target, sourceResolvableType.getGenerics());
        return targetResolvableType.isAssignableFrom(sourceResolvableType);
    }

    return ResolvableType.forClass(target).isAssignableFrom(sourceResolvableType);
